// Cat Clubhouse, design round 2: sound.
// Game sounds are small synthesizer cues, the way the operator's lpingcat Playtime games make them (lpingcat components/play/tower-audio.ts):
// nothing to download during play. Cat voices are the short recordings lpingcat ships (public/art/sounds/v2, Pixabay), one voice per cat,
// played a little higher or lower so the eight sound different.
(() => {
  // [hz, seconds, volume, delay, end hz]
  const CUES = {
    tap: [[520, 0.05, 0.028, 0, 440]],
    flip: [[392, 0.06, 0.032, 0, 330]], unflip: [[300, 0.07, 0.024, 0, 220]],
    pair: [[659, 0.12, 0.04], [880, 0.17, 0.034, 0.09]],
    token: [[330, 0.1, 0.04, 0, 165]], land: [[225, 0.08, 0.031, 0, 130]],
    yarn: [[440, 0.07, 0.03, 0, 300]], merge: [[523, 0.1, 0.04, 0, 784]],
    chain: [[659, 0.1, 0.04], [784, 0.1, 0.04, 0.07], [1047, 0.17, 0.034, 0.14]], tangle: [[180, 0.18, 0.04, 0, 110]],
    spring: [[265, 0.25, 0.05, 0, 800]], bop: [[392, 0.12, 0.05, 0, 880]], fall: [[212, 0.24, 0.05, 0, 92]],
    boop: [[880, 0.07, 0.05, 0, 1320], [1320, 0.09, 0.03, 0.05]],
    windup: [[300, 0.32, 0.03, 0, 520]], prank: [[420, 0.12, 0.04, 0, 250], [250, 0.16, 0.04, 0.1, 180]],
    tick: [[1000, 0.03, 0.02]], drum: [[160, 0.05, 0.04, 0, 120], [160, 0.05, 0.04, 0.09, 120]],
    lights: [[660, 0.22, 0.03, 0, 220]], lamp: [[220, 0.2, 0.03, 0, 660]],
    slip: [[700, 0.26, 0.028, 0, 350]], swap: [[330, 0.3, 0.025, 0, 392], [392, 0.3, 0.025, 0.28, 330]],
    win: [[587, 0.19, 0.04], [784, 0.22, 0.04, 0.09], [1047, 0.3, 0.032, 0.19]],
    lose: [[392, 0.2, 0.038, 0, 330], [294, 0.32, 0.038, 0.18, 220]],
    stamp: [[784, 0.17, 0.039], [1175, 0.2, 0.024, 0.045]],
    thump: [[150, 0.1, 0.045, 0, 70]], pop: [[600, 0.06, 0.03, 0, 900]], heart: [[880, 0.1, 0.022], [1175, 0.14, 0.018, 0.08]],
    whoosh: [[240, 0.16, 0.02, 0, 520]], open: [[523, 0.16, 0.035], [659, 0.16, 0.035, 0.1], [784, 0.16, 0.035, 0.2], [1047, 0.3, 0.03, 0.3]],
  };
  // One recording and one pitch per cat. Purrs are shared.
  const VOICE = {
    tofu: ["dragon-studio-cat-meow-401729", 0.82], mint: ["virtual_vibes-cute-cat-meow-400946", 1.0], mango: ["stu9-cute-cat-352656", 1.28],
    jelly: ["dragon-studio-cute-cat-meow-472372", 1.06], ollie: ["soundreality-cat-meow-fx-461188", 1.12], button: ["virtual_vibes-cat-meow-sound-383823", 1.18],
    sumi: ["dragon-studio-cat-meowing-401730", 0.9], plum: ["freesound_community-cat-98721", 0.8],
  };
  const PURR = "dragon-studio-cat-purr-sfx-482870";
  let ctx = null, on = true, last = {};
  const stats = { cues: 0, voices: 0, failed: 0 };   // counted so a test can tell that sound really played
  const buffers = {};
  const recordings = {
  "dragon-studio-cat-meow-401729": "data:audio/mpeg;base64,",
  "dragon-studio-cat-meowing-401730": "data:audio/mpeg;base64,",
  "dragon-studio-cat-purr-sfx-482870": "data:audio/mpeg;base64,",
  "dragon-studio-cute-cat-meow-472372": "data:audio/mpeg;base64,",
  "freesound_community-cat-98721": "data:audio/mpeg;base64,",
  "soundreality-cat-meow-fx-461188": "data:audio/mpeg;base64,",
  "stu9-cute-cat-352656": "data:audio/mpeg;base64,",
  "virtual_vibes-cat-meow-sound-383823": "data:audio/mpeg;base64,",
  "virtual_vibes-cute-cat-meow-400946": "data:audio/mpeg;base64,"
};
  try { on = localStorage.getItem("cc-sound") !== "off"; } catch (e) { /* private mode: sound stays on for this visit */ }

  function unlock() {
    if (!on) return;
    try {
      const A = window.AudioContext || window.webkitAudioContext; if (!A) return;
      ctx = ctx || new A();
      if (ctx.state !== "running") ctx.resume().catch(() => {});
    } catch (e) { /* a host without audio stays silent */ }
  }
  const ready = () => on && ctx && ctx.state === "running" && !document.hidden;
  function cue(name, { rate = 1, gain = 1 } = {}) {
    if (!ready() || !CUES[name]) return;
    const now = performance.now(); if (now - (last[name] ?? -1e9) < 40) return; last[name] = now;   // never the same cue twice in one frame
    stats.cues++;
    for (const [hz, len, vol, delay = 0, end = hz] of CUES[name]) {
      const at = ctx.currentTime + delay, o = ctx.createOscillator(), g = ctx.createGain();
      o.frequency.setValueAtTime(hz * rate, at); o.frequency.exponentialRampToValueAtTime(Math.max(40, end * rate), at + len);
      g.gain.setValueAtTime(0.001, at); g.gain.exponentialRampToValueAtTime(vol * gain, at + 0.013); g.gain.exponentialRampToValueAtTime(0.001, at + len);
      o.connect(g).connect(ctx.destination); o.onended = () => { o.disconnect(); g.disconnect(); };
      o.start(at); o.stop(at + len + 0.01);
    }
  }
  function load(file) {
    if (buffers[file]) return buffers[file];
    return (buffers[file] = fetch(recordings[file]).then(r => r.arrayBuffer()).then(b => new Promise((ok, no) => ctx.decodeAudioData(b, ok, no))).catch(() => null));
  }
  function sample(file, rate, gain) {
    if (!ready()) return;
    load(file).then(buf => {
      if (!buf) stats.failed++;
      if (!buf || !ready()) return;
      stats.voices++;
      const s = ctx.createBufferSource(), g = ctx.createGain(); s.buffer = buf; s.playbackRate.value = rate; g.gain.value = gain;
      s.connect(g).connect(ctx.destination); s.onended = () => { s.disconnect(); g.disconnect(); }; s.start();
    });
  }
  // A cat speaks. kind: "meow" (its own voice), "squeak" (a short high one, for a boop), "low" (a grumble, for a loss), "purr".
  function cat(id, kind = "meow") {
    const v = VOICE[id]; if (!v) return;
    const now = performance.now(); if (now - (last["cat" + id] ?? -1e9) < 500) return; last["cat" + id] = now;
    if (kind === "purr") return sample(PURR, 1, 0.5);
    sample(v[0], v[1] * (kind === "squeak" ? 1.35 : kind === "low" ? 0.78 : 1), kind === "squeak" ? 0.42 : 0.55);
  }
  function set(value) { on = value; try { localStorage.setItem("cc-sound", on ? "on" : "off"); } catch (e) { /* not kept */ } if (on) unlock(); else if (ctx) ctx.suspend().catch(() => {}); }
  // Browsers only let sound start from a touch. The first touch anywhere opens it, and loads the voices.
  // (iPhone Safari counts the end of a touch and a click as the gesture, so those open it too.)
  for (const type of ["pointerdown", "touchend", "click"]) addEventListener(type, () => { unlock(); if (ready()) for (const id in VOICE) load(VOICE[id][0]); }, { passive: true, capture: true });
  document.addEventListener("click", e => { if (e.target.closest("[data-go], .button, .tab, .row, .pick, .chip, .switch, .game-tile, .cat-card, .starter")) cue("tap"); }, true);
  window.Sound = { cue, cat, unlock, set, stats, state: () => (ctx ? ctx.state : "none"), get on() { return on; } };
})();
